# Getting Started with iOS Development

iOS powers iPhones, iPads, and other Apple devices with 1.5+ billion active users worldwide. Learn to build beautiful, performant apps using Swift and SwiftUI.

## Why iOS Development?

- **Premium Market**: iOS users spend more on apps
- **Quality Ecosystem**: Consistent devices and OS versions
- **Career Growth**: High-paying opportunities
- **Modern Tools**: Swift and SwiftUI make development enjoyable
- **App Store**: Direct monetization platform

## Setting Up Xcode

1. Get a Mac (required for iOS development)
2. Download Xcode from Mac App Store (free)
3. Install Command Line Tools
4. Set up iPhone/iPad Simulator

## Swift Basics

### Variables and Constants

```swift
// Constants (immutable)
let name = "John"
let age = 25

// Variables (mutable)
var score = 0
var isStudent = true

// Type annotations
let price: Double = 9.99
let letter: Character = "A"
let text: String = "Hello, World!"
```

### Optionals (Handling nil)

```swift
// Optional - can be nil
var email: String? = nil
email = "john@example.com"

// Unwrapping optionals
if let unwrappedEmail = email {
    print("Email: \(unwrappedEmail)")
} else {
    print("No email")
}

// Nil coalescing
let displayName = email ?? "Guest"

// Force unwrap (use carefully!)
let definiteEmail = email!
```

### Functions

```swift
// Basic function
func greet(name: String) -> String {
    return "Hello, \(name)!"
}

// Multiple parameters
func add(a: Int, b: Int) -> Int {
    return a + b
}

// Default parameters
func createUser(name: String, age: Int = 18) {
    print("User: \(name), Age: \(age)")
}

// Usage
let message = greet(name: "Alice")
let sum = add(a: 5, b: 3)
createUser(name: "Bob")  // Uses default age
```

### Structs and Classes

```swift
// Struct (value type, preferred in SwiftUI)
struct User {
    let id: Int
    var name: String
    var email: String

    func displayInfo() -> String {
        return "\(name) (\(email))"
    }
}

// Usage
var user = User(id: 1, name: "John", email: "john@example.com")
user.name = "John Doe"
print(user.displayInfo())

// Class (reference type)
class ViewController {
    var title: String

    init(title: String) {
        self.title = title
    }
}
```

### Collections

```swift
// Arrays
let numbers = [1, 2, 3, 4, 5]
var mutableArray = ["A", "B", "C"]
mutableArray.append("D")

// Dictionaries
let userScores = [
    "Alice": 95,
    "Bob": 87,
    "Charlie": 92
]

// Higher-order functions
let evenNumbers = numbers.filter { $0 % 2 == 0 }
let doubled = numbers.map { $0 * 2 }
let sum = numbers.reduce(0, +)
```

## SwiftUI Basics

### Your First View

```swift
import SwiftUI

struct ContentView: View {
    var body: some View {
        VStack {
            Text("Hello, SwiftUI!")
                .font(.largeTitle)
                .foregroundColor(.blue)

            Image(systemName: "star.fill")
                .font(.system(size: 50))
                .foregroundColor(.yellow)

            Button("Tap Me") {
                print("Button tapped")
            }
            .buttonStyle(.bordered)
        }
        .padding()
    }
}
```

### State Management

```swift
struct CounterView: View {
    // State variable triggers UI updates
    @State private var count = 0

    var body: some View {
        VStack(spacing: 20) {
            Text("Count: \(count)")
                .font(.title)

            HStack {
                Button("Decrement") {
                    count -= 1
                }
                .buttonStyle(.bordered)

                Button("Increment") {
                    count += 1
                }
                .buttonStyle(.borderedProminent)
            }
        }
        .padding()
    }
}
```

### Lists

```swift
struct TodoListView: View {
    let todos = [
        "Learn Swift",
        "Build iOS app",
        "Deploy to App Store"
    ]

    var body: some View {
        NavigationView {
            List(todos, id: \.self) { todo in
                HStack {
                    Image(systemName: "checkmark.circle")
                        .foregroundColor(.green)
                    Text(todo)
                }
            }
            .navigationTitle("My Todos")
        }
    }
}
```

## Building a Complete Todo App

```swift
import SwiftUI

struct Todo: Identifiable {
    let id = UUID()
    var text: String
    var isCompleted: Bool = false
}

struct TodoAppView: View {
    @State private var todos = [
        Todo(text: "Learn Swift"),
        Todo(text: "Build iOS app")
    ]

    @State private var newTodoText = ""

    var body: some View {
        NavigationView {
            VStack {
                // Add new todo
                HStack {
                    TextField("New todo", text: $newTodoText)
                        .textFieldStyle(.roundedBorder)

                    Button(action: addTodo) {
                        Image(systemName: "plus.circle.fill")
                            .font(.title)
                    }
                    .disabled(newTodoText.isEmpty)
                }
                .padding()

                // Todo list
                List {
                    ForEach($todos) { $todo in
                        TodoRow(todo: $todo)
                    }
                    .onDelete(perform: deleteTodos)
                }
            }
            .navigationTitle("My Todos")
            .toolbar {
                EditButton()
            }
        }
    }

    func addTodo() {
        let todo = Todo(text: newTodoText)
        todos.append(todo)
        newTodoText = ""
    }

    func deleteTodos(at offsets: IndexSet) {
        todos.remove(atOffsets: offsets)
    }
}

struct TodoRow: View {
    @Binding var todo: Todo

    var body: some View {
        HStack {
            Button(action: { todo.isCompleted.toggle() }) {
                Image(systemName: todo.isCompleted ? 
                    "checkmark.circle.fill" : 
                    "circle")
                .foregroundColor(todo.isCompleted ? .green : .gray)
            }
            .buttonStyle(.plain)

            Text(todo.text)
                .strikethrough(todo.isCompleted)
                .foregroundColor(todo.isCompleted ? .gray : .primary)
        }
    }
}
```

